/* World Atelier - interface (app.js)
 * Código da aplicação. A única ligação com o disco é o objeto STORE (storage.js):
 *   STORE.load()          -> lê os dados
 *   STORE.save(() => S)   -> agenda o salvamento automático
 * No navegador (sem Electron) o STORE usa localStorage; no app desktop usa a pasta escolhida.
 */
const $=s=>document.querySelector(s);
const uiLanguage=()=>{try{const saved=localStorage.getItem('world-atelier-language');if(saved==='en'||saved==='pt-BR')return saved}catch(_){}try{return window.atelier?.info?.().language==='en'?'en':'pt-BR'}catch(_){return 'pt-BR'}};
const D=(pt,en)=>uiLanguage()==='en'?en:pt;
// Built-in spectrum presets are interface examples, not user-authored prose.
// Only recognized preset terms are switched; arbitrary custom labels are kept.
const SPECTRUM_PRESET_VALUES={
 'Introvertido':'Introverted','Extrovertido':'Extroverted',
 'Caótico':'Chaotic','Comportado':'Orderly','Frio':'Cold','Sensível':'Sensitive'
};
const SPECTRUM_PRESET_GROUPS={
 'Geral':'General','Mental':'Mental','Social':'Social','Emocional':'Emotional','Moral':'Moral','Físico':'Physical'
};
const CHARACTER_SCORE_PRESETS={'Inteligência':'Intelligence','Carisma':'Charisma'};
function localizedPresetValue(value,map){
 const source=String(value??'');
 if(uiLanguage()==='en')return map[source]||source;
 for(const [pt,en] of Object.entries(map))if(en===source)return pt;
 return source;
}
function localizeSpectrumPresets(){
 let changed=false;
 for(const world of S.worlds||[])for(const character of world.chars||[]){
  for(const spectrum of character.spectra||[]){
   for(const [key,map] of [['l',SPECTRUM_PRESET_VALUES],['r',SPECTRUM_PRESET_VALUES],['g',SPECTRUM_PRESET_GROUPS]]){
    const next=localizedPresetValue(spectrum[key],map);
    if(next!==spectrum[key]){spectrum[key]=next;changed=true;}
   }
  }
  for(const score of character.scores||[]){const next=localizedPresetValue(score.n,CHARACTER_SCORE_PRESETS);if(next!==score.n){score.n=next;changed=true;}}
 }
 return changed;
}
