 const notes=w.skillNotes.map((note,i)=>`<article class="pw skill-note-card" style="margin-top:12px;border-left:5px solid ${esc(note.color||'#d6a85c')}"><div class="top skill-note-head" style="margin:0;gap:8px;align-items:center"><button class="story-collapse" data-act="toggleSkillNote" data-id="${note.id}" title="${D('Minimizar / expandir','Collapse / expand')}">${note.cl?'＋':'−'}</button><span class="skill-note-swatch" style="display:inline-block;width:18px;height:18px;border-radius:5px;background:${esc(note.color||'#d6a85c')};border:1px solid var(--line);flex:none"></span><div style="flex:1;min-width:120px">${I('w',`skillNotes.${i}.n`,note.n||'',D('Nome da anotação','Note title'))}</div><input type="color" value="${esc(note.color||'#d6a85c')}" data-s="w" data-p="skillNotes.${i}.color" data-re="1" title="${D('Cor do bloco','Note block color')}" style="width:42px;padding:2px"><button class="x dg" data-act="delSkillNote" data-id="${note.id}" title="${D('Apagar anotação','Delete note')}">✕</button></div>${note.cl?'':T('w',`skillNotes.${i}.v`,note.v||'',D('Escreva suas anotações aqui...','Write your notes here...'),150)}</article>`).join('');
