 return `<div class="top"><button data-act="cy" data-d="-1">◀</button>${yr(c,'cy',y,'ui')}<button data-act="cy" data-d="1">▶</button><span style="color:var(--mute)">Este ano tem ${ylen(c)+yadj(c,y)} dias. Cada ponto colorido é um evento ou data anual, na cor da sua tag. Quadradinhos são ciclos de personagens.</span></div>${pn}<div class="cm">${ms}</div>`;
