function relGraph(w){
 const RL=relsFor(w),ids=[...new Set(RL.flatMap(({r})=>r.members))],ch=ids.map(id=>findCh(id)?.c).filter(Boolean);
 if(ch.length<2)return '<div class="empty">Crie vínculos com 2 ou mais membros para ver o grafo.</div>';
 const cx=260,cy=260,pos={},tc=id=>(w.rcfg?.types.find(t=>t.id===id)||{c:'#999'}).c,off={},used={},tcm={};
 ch.forEach((c,i)=>{const a=i/ch.length*2*Math.PI-Math.PI/2;pos[c.id]=[cx+195*Math.cos(a),cy+195*Math.sin(a)]});
 let es='';
 RL.forEach(({r,h})=>{const m=r.members.filter(id=>pos[id]);used[r.type]=1;tcm[r.type]=h.rcfg?.types.find(t=>t.id===r.type)||{c:'#999',n:r.type};for(let i=0;i<m.length;i++)for(let j=i+1;j<m.length;j++){const [x1,y1]=pos[m[i]],[x2,y2]=pos[m[j]],key=[m[i],m[j]].sort().join(),n=off[key]=(off[key]||0)+1,mx=(x1+x2)/2,my=(y1+y2)/2,dx=y2-y1,dy=x1-x2,l=Math.hypot(dx,dy)||1,o=(n-1)*34*(n%2?-1:1)*Math.ceil((n-1)/2+.5);es+=`<path d="M${x1} ${y1}Q${mx+dx/l*o} ${my+dy/l*o} ${x2} ${y2}" fill="none" stroke="${tcm[r.type].c}" stroke-width="3.5" opacity=".85"><title>${esc(r.n)}</title></path>`}});
 const nodes=ch.map((c,i)=>{const [x,y]=pos[c.id],im=mainImg(c);return `<g data-act="openN" data-id="${c.id}" style="cursor:pointer"><clipPath id="cp${i}"><circle cx="${x}" cy="${y}" r="32"/></clipPath><circle cx="${x}" cy="${y}" r="34" style="fill:var(--card);stroke:var(--line);stroke-width:2"/>${im?`<image href="${im.src}" x="${x-32}" y="${y-32}" width="64" height="64" clip-path="url(#cp${i})" preserveAspectRatio="xMidYMid slice"/>`:`<text x="${x}" y="${y+7}" text-anchor="middle" font-size="22" style="fill:var(--mute)">${esc((c.name||'?')[0])}</text>`}<text x="${x}" y="${y+52}" text-anchor="middle" font-size="13" style="fill:var(--tx)">${esc(c.name||'?')}</text></g>`}).join('');
 return `<div style="margin-bottom:8px">${Object.values(tcm).map(t=>`<span class="chip" style="border-color:${t.c};color:${t.c}">${esc(t.n)}</span>`).join('')}</div><svg viewBox="0 0 520 520" style="width:100%;max-width:680px;display:block">${es}${nodes}</svg><p style="color:var(--mute);font-size:13px">Clique num personagem para abrir a ficha. O grafo mostra o momento ativo de cada vínculo.</p>`;
}
