function htmlToMarkdown(raw,notes=[]){
 const html=raw&&raw[0]==='\u2063'?raw.slice(1):raw||'',doc=new DOMParser().parseFromString('<body>'+clean(html)+'</body>','text/html');
 const walk=n=>{if(n.nodeType===3)return n.nodeValue;if(n.nodeType!==1)return '';const tag=n.tagName,inside=[...n.childNodes].map(walk).join('');if(tag==='BR')return '\n';if(tag==='B'||tag==='STRONG')return '**'+inside+'**';if(tag==='I'||tag==='EM')return '*'+inside+'*';if(tag==='H3')return '\n### '+inside+'\n\n';if(tag==='LI')return '- '+inside+'\n';if(tag==='UL'||tag==='OL')return inside+'\n';if(tag==='P'||tag==='DIV'||tag==='BLOCKQUOTE')return inside+'\n\n';if(tag==='SPAN'&&n.classList.contains('note-ref')){const ix=notes.findIndex(x=>x.id===n.dataset.noteId);return `[nota ${ix>=0?ix+1:'?'}]`;}if(tag==='A')return inside;return inside};
 return [...doc.body.childNodes].map(walk).join('').replace(/\n{3,}/g,'\n\n').trim();
}
