 for(const ar of arcs){md+=`## ${ar.n||'Arco sem título'}\n\n`;const scenario=ar.scenario?S.worlds.find(x=>x.id===ar.scenario)?.name:'';if(scenario)md+=`**Cenário:** ${scenario}\n\n`;const t=storyDateText(ar,root);if(t)md+=`**Época:** ${t}\n\n`;
  for(const ch of (ar.chapters||[]).filter(x=>!chapterId||x.id===chapterId)){md+=`### ${ch.n||'Capítulo sem título'}\n\n`;if(ch.scenario){const sc=S.worlds.find(x=>x.id===ch.scenario);if(sc)md+=`**Cenário:** ${sc.name}\n\n`}const ct=storyDateText(ch,root);if(ct)md+=`**Época:** ${ct}\n\n`;if(ch.d)md+=`*Resumo:* ${ch.d}\n\n`;if(ch.text)md+=htmlToMarkdown(ch.text,ch.footnotes||[])+'\n\n';if(ch.footnotes?.length){md+='**Notas / Easter eggs**\n\n'+ch.footnotes.map((n,i)=>`${i+1}. ${n.text}`).join('\n')+'\n\n'}md+='---\n\n'}
 }
