 if(obj.timeYear!==undefined&&obj.timeYear!==''){const ww=S.worlds.find(x=>x.id===(obj.timeWorld||root.id))||root,cal=cc(ww),mo=cal.months.find(x=>x.id===obj.timeMonth);return `Ano ${obj.timeYear}${mo?' · '+mo.n:''}${obj.timeDay?' · dia '+obj.timeDay:''}`}
 return '';
