function globalSearchResults(query,scope=''){
 const q=query.trim().toLocaleLowerCase('pt-BR');if(!q)return '<div class="empty" style="padding:22px">Digite para pesquisar mundos, OCs, itens, citações, cenários, locais, lore e capítulos.</div>';
 const out=[],add=(kind,label,sub,attrs)=>{out.push(`<div class="search-result" data-act="searchGo" data-kind="${kind}" ${Object.entries(attrs).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}><span class="search-kind">${kind==='char'?'Personagem':kind==='world'?'Mundo':kind==='wiki'?'Lore':kind==='place'?'Local':kind==='item'?'Item':kind==='species'?'Espécie':kind==='map'?'Mapa':kind==='dictionary'?'Dicionário':kind==='quote'?'Citação':kind==='scene'?'Cenário':kind==='story'?'História':kind==='arc'?'Arco / volume':'Capítulo'}</span><span><b>${esc(label||'Sem título')}</b><small>${esc(sub||'')}</small></span></div>`)};
 const hit=x=>(x??'').toLocaleLowerCase('pt-BR').includes(q);
 S.worlds.filter(w=>!scope||rootOf(w).id===scope||w.id===scope).forEach(w=>{
  if(hit(w.name)||hit(w.desc))add('world',w.name,'Mundo',{'wid':w.id});
  w.chars.forEach(c=>{
   const sub=`${w.name} · Personagem`;
   if(hit(c.name)||hit(c.story)||hit(c.pers)||hit(c.look))add('char',c.name,sub,{'wid':w.id,'id':c.id});
   (c.items||[]).forEach(it=>{if(hit(it.n)||hit(it.d))add('item',it.n,`${c.name} · ${w.name}`,{'wid':w.id,'id':it.id,'cid':c.id})});
   (c.quotes||[]).forEach(v=>{if(hit(v.text)||hit(v.context))add('quote',v.text,`${c.name} · ${w.name}`,{'wid':w.id,'id':v.id||'','cid':c.id})});
  });
  w.wiki.forEach(x=>{if(hit(x.t)||hit(clean(x.b||'').replace(/<[^>]*>/g,' ')))add('wiki',x.t,w.name,{'wid':w.id,'id':x.id})});
  w.locations.forEach(x=>{if(hit(x.n)||hit(x.d))add('place',x.n,w.name,{'wid':w.id,'id':x.id})});
  (w.worldItems||[]).forEach(x=>{if(hit(x.n)||hit(x.d))add('item',x.n,`${w.name} · Item`,{'wid':w.id,'id':x.id})});
  (w.species||[]).forEach(x=>{if(hit(x.n)||hit(x.scientific)||hit(x.d))add('species',x.n,`${w.name} · Espécie`,{'wid':w.id,'id':x.id})});
  (w.maps||[]).forEach(x=>{if(hit(x.n))add('map',x.n,`${w.name} · Mapa`,{'wid':w.id,'id':x.id})});
  (w.languages||[]).forEach(lang=>(lang.words||[]).forEach(v=>{if(hit(v.word)||hit(v.translation))add('dictionary',v.word,`${lang.n} · ${v.translation}`,{'wid':w.id,'id':lang.id})}));
  w.stories.forEach(st=>{if(hit(st.n)||hit(st.d))add('story',st.n,w.name,{'wid':w.id,'id':st.id});(st.arcs||[]).forEach(a=>{if(hit(a.n))add('arc',a.n,`${st.n} · ${w.name}`,{'wid':w.id,'id':a.id,'sid':st.id});(a.chapters||[]).forEach(ch=>{if(hit(ch.n)||hit(ch.d)||hit(htmlToMarkdown(ch.text,ch.footnotes||[]))||(ch.footnotes||[]).some(n=>hit(n.text)))add('chapter',ch.n,`${st.n} · ${a.n} · ${w.name}`,{'wid':w.id,'id':ch.id,'sid':st.id,'aid':a.id})})})});
  if(rootOf(w).id===w.id){(w.scenes||[]).forEach(sc=>{if(hit(sc.n)||hit(sc.d))add('scene',sc.n,`Cenário · ${w.name}`,{'wid':w.id,'id':sc.id})});(w.linearEvents||[]).forEach(ev=>{if(hit(ev.n)||hit(ev.d)||hit(ev.tag)||hit(ev.when))add('linear',ev.n,`Linha do tempo livre · ${w.name}`,{'wid':w.id,'id':ev.id})})}
 });
 return out.length?out.slice(0,60).join(''):'<div class="empty" style="padding:22px">Nenhum resultado encontrado.</div>';
}
