document.addEventListener('dragstart',e=>{const card=e.target.closest?.('[data-scene-drag]');if(card){ui.dragScene=card.dataset.sceneDrag;e.dataTransfer?.setData('text/plain',ui.dragScene);if(e.dataTransfer)e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{const col=e.target.closest?.('[data-scene-stage]');if(col&&ui.dragScene){e.preventDefault();col.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const col=e.target.closest?.('[data-scene-stage]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over')});
document.addEventListener('drop',e=>{const col=e.target.closest?.('[data-scene-stage]');if(!col||!ui.dragScene)return;e.preventDefault();const id=ui.dragScene;ui.dragScene='';document.querySelectorAll('.scene-column.drag-over').forEach(x=>x.classList.remove('drag-over'));const root=rootOf(W());const sc=root?.scenes?.find(x=>x.id===id);if(sc){sc.status=col.dataset.sceneStage;save();render()}});
document.addEventListener('dragend',()=>{ui.dragScene='';document.querySelectorAll('.scene-column.drag-over').forEach(x=>x.classList.remove('drag-over'))});
if(innerWidth<720)document.body.classList.add('col');
render();
